+package ai.unifiedprocess.petclinic.vet.ui;
+
+import ai.unifiedprocess.petclinic.PetClinicTestBase;
+import ai.unifiedprocess.petclinic.UseCase;
+import ai.unifiedprocess.petclinic.welcome.ui.WelcomeView;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.grid.GridTester;
+import com.vaadin.flow.component.sidenav.SideNavItem;
+import org.jooq.DSLContext;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+
+import static ai.unifiedprocess.demo.petclinic.database.Tables.VETS;
+import static ai.unifiedprocess.demo.petclinic.database.Tables.VET_SPECIALTIES;
+import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+
+/**
+ * UC-002: View Veterinarians.
+ */
+class UC002ViewVeterinariansTest extends PetClinicTestBase {
+
+    private static final int FIRST_NAME = 0;
+    private static final int LAST_NAME = 1;
+    private static final int SPECIALTIES = 2;
+
+    @Autowired
+    private DSLContext dsl;
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-003")
+    void veterinariansLinkOpensTheGridWithoutAuthentication() {
+        navigate(WelcomeView.class);
+
+        SideNavItem vetsLink = assertDoesNotThrow(() -> find(SideNavItem.class)
+                        .withPropertyValue(SideNavItem::getLabel, "Veterinarians").single(),
+                "Expected a Veterinarians navigation item");
+        assertDoesNotThrow(() -> UI.getCurrent().navigate(vetsLink.getPath()),
+                "Expected the Veterinarians link to open without authentication");
+
+        assertEquals("vets", UI.getCurrent().getInternals().getActiveViewLocation().getPath());
+        assertDoesNotThrow(() -> find(Grid.class).single(), "Expected the veterinarians grid");
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void gridShowsEveryVetWithNameAndSpecialties() {
+        navigate(VetsView.class);
+
+        GridTester<Grid<Object>, Object> grid = test(vetsGrid());
+        assertEquals(6, grid.size());
+        assertEquals("First Name", grid.getHeaderCell(FIRST_NAME));
+        assertEquals("Last Name", grid.getHeaderCell(LAST_NAME));
+        assertEquals("Specialties", grid.getHeaderCell(SPECIALTIES));
+
+        assertEquals("James", grid.getCellText(0, FIRST_NAME));
+        assertEquals("Carter", grid.getCellText(0, LAST_NAME));
+        assertEquals("none", grid.getCellText(0, SPECIALTIES));
+        assertEquals("Helen", grid.getCellText(3, FIRST_NAME));
+        assertEquals("Leary", grid.getCellText(3, LAST_NAME));
+        assertEquals("radiology", grid.getCellText(3, SPECIALTIES));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-002")
+    void specialtiesAreListedAlphabetically() {
+        navigate(VetsView.class);
+
+        GridTester<Grid<Object>, Object> grid = test(vetsGrid());
+        // Linda Douglas holds surgery (id 2) and dentistry (id 3): the id order
+        // differs from the alphabetical one the rule demands.
+        assertEquals("Douglas", grid.getCellText(1, LAST_NAME));
+        assertEquals("dentistry, surgery", grid.getCellText(1, SPECIALTIES));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-001")
+    void gridLoadsLazilyFromTheBackend() {
+        navigate(VetsView.class);
+
+        Grid<?> grid = vetsGrid();
+        assertFalse(grid.getDataProvider().isInMemory(),
+                "Expected the grid to fetch rows from the backend as the visitor scrolls");
+        assertDoesNotThrow(grid::getLazyDataView, "Expected a lazy data view on the veterinarians grid");
+    }
+
+    @Test
+    @UseCase(id = "UC-002", scenario = "A1: No Veterinarians Registered")
+    void noVeterinariansRendersAnEmptyGrid() {
+        dsl.deleteFrom(VET_SPECIALTIES).execute();
+        dsl.deleteFrom(VETS).execute();
+
+        navigate(VetsView.class);
+
+        assertEquals(0, test(vetsGrid()).size());
+    }
+
+    @SuppressWarnings("unchecked")
+    private Grid<Object> vetsGrid() {
+        return assertDoesNotThrow(() -> (Grid<Object>) find(Grid.class).single(),
+                "Expected exactly one veterinarians grid");
+    }
+}
